style.css:
@-moz-document domain("roblox.com") {
/* Target the profile picture container */
  .profile-avatar-image {
    transform: rotateY(15deg) rotateX(-5deg);
    -webkit-transform: rotateY(15deg) rotateX(-5deg);
    -moz-transform: rotateY(15deg) rotateX(-5deg);
    -o-transform: rotateY(15deg) rotateX(-5deg);
    -ms-transform: rotateY(15deg) rotateX(-5deg);
  }

  /* Hide emotes */
  .profile-emote,
  .profile-status,
  .profile-header-emote {
    display: none !important;
  }
}
